// Offline-first cache. precache.js (generated by scripts/build-web.sh) defines BUILD and PRECACHE;
// a new build changes it, which makes the browser install a new worker next to the running one.
importScripts('precache.js');

const CACHE = `last-dev-${self.BUILD}`;
const scoped = (p) => new URL(p, self.registration.scope).href;
const listed = new Set(self.PRECACHE.map(scoped));
const INDEX = scoped('./');

self.addEventListener('install', (event) => {
  event.waitUntil((async () => {
    const cache = await caches.open(CACHE);
    // The shell must be complete or the install fails (and the old build keeps running).
    const core = self.PRECACHE.filter((p) => p === 'index.html' || p.startsWith('pkg/') || p === 'manifest.webmanifest');
    await cache.addAll(['./', ...core.map(scoped)]);
    // Assets are best effort: on a quota error the game still streams them from the network.
    for (const p of self.PRECACHE) {
      if (core.includes(p)) continue;
      try {
        await cache.add(scoped(p));
      } catch (e) {
        console.warn('[sw] cache full or fetch failed, continuing online:', p, e && e.name);
        break;
      }
    }
  })());
});

// No skipWaiting on install: the page shows a toast and asks, so a build never swaps mid-game.
self.addEventListener('message', (event) => {
  if (event.data === 'skip-waiting') self.skipWaiting();
});

self.addEventListener('activate', (event) => {
  event.waitUntil((async () => {
    for (const k of await caches.keys()) {
      if (k.startsWith('last-dev-') && k !== CACHE) await caches.delete(k);
    }
    await self.clients.claim();
  })());
});

self.addEventListener('fetch', (event) => {
  const req = event.request;
  if (req.method !== 'GET') return;
  const url = new URL(req.url);
  // Cross-origin and the co-op websocket endpoint always go to the network.
  if (url.origin !== self.location.origin || url.pathname.endsWith('/ws')) return;
  const key = url.origin + url.pathname;
  const isIndex = req.mode === 'navigate' || key === INDEX || key === scoped('index.html');
  if (isIndex) {
    event.respondWith((async () => {
      const cache = await caches.open(CACHE);
      try {
        const fresh = await fetch(req);
        if (fresh.ok) cache.put(INDEX, fresh.clone()).catch(() => {});
        return fresh;
      } catch (e) {
        return (await cache.match(INDEX)) || Response.error();
      }
    })());
  } else if (listed.has(key)) {
    event.respondWith((async () => {
      const hit = await caches.match(key, { cacheName: CACHE });
      return hit || fetch(req);
    })());
  }
});
